// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this)); // owner is the deployer (this test contract)

        vm.deal(address(c), 1 ether);
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: any non-owner caller must NOT be able to destroy c;
        // the call must revert, so c survives with its balance intact.
        assertTrue(!ok && address(c).balance == 1 ether);
    }
}
